"""Out-of-place foreach scalar-list subtraction (aten::_foreach_sub.ScalarList).

out[i] = self[i] - scalars[i], with a fresh, contiguous output tensor per input.

Small contiguous groups of one dtype are fused into a single Triton launch: the
grid covers the concatenation of their element ranges, each program picks its
slot from host-computed program-space boundaries, and the slot's base pointer is
formed by adding a per-slot element delta to the first tensor's pointer.
Large tensors use one persistent per-tensor launch (grid capped at the backend
grid limit). Non-contiguous tensors use a generic up-to-8D strided kernel.
"""

import torch
import triton
import triton.language as tl

_MAX_SLOTS = 8
_MAX_GRID = 65535
_FUSE_LIMIT = 1 << 27


@triton.jit
def _sub_contig_kernel(
    x_ptr, y_ptr, n, s, BLOCK: tl.constexpr, EVEN: tl.constexpr, I64: tl.constexpr
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    if I64:
        n64 = n.to(tl.int64)
        step = nprog.to(tl.int64) * BLOCK
        start = pid.to(tl.int64) * BLOCK
        for off in range(start, n64, step):
            offs = off + tl.arange(0, BLOCK).to(tl.int64)
            if EVEN:
                x = tl.load(x_ptr + offs)
                acc = x.to(tl.float32) - s
                tl.store(y_ptr + offs, acc.to(y_ptr.dtype.element_ty))
            else:
                mask = offs < n64
                x = tl.load(x_ptr + offs, mask=mask, other=0)
                acc = x.to(tl.float32) - s
                tl.store(y_ptr + offs, acc.to(y_ptr.dtype.element_ty), mask=mask)
    else:
        step = nprog * BLOCK
        start = pid * BLOCK
        for off in range(start, n, step):
            offs = off + tl.arange(0, BLOCK)
            if EVEN:
                x = tl.load(x_ptr + offs)
                acc = x.to(tl.float32) - s
                tl.store(y_ptr + offs, acc.to(y_ptr.dtype.element_ty))
            else:
                mask = offs < n
                x = tl.load(x_ptr + offs, mask=mask, other=0)
                acc = x.to(tl.float32) - s
                tl.store(y_ptr + offs, acc.to(y_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _sub_strided_kernel(
    x_ptr,
    y_ptr,
    n,
    n0,
    n1,
    n2,
    n3,
    n4,
    n5,
    n6,
    n7,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    xs5,
    xs6,
    xs7,
    ys0,
    ys1,
    ys2,
    ys3,
    ys4,
    ys5,
    ys6,
    ys7,
    s,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    step = nprog * BLOCK
    start = pid * BLOCK
    for off in range(start, n, step):
        offs = off + tl.arange(0, BLOCK)
        rem = offs
        xoff = tl.zeros([BLOCK], dtype=tl.int64)
        yoff = tl.zeros([BLOCK], dtype=tl.int64)
        if RANK > 7:
            idx = rem % n7
            rem = rem // n7
            xoff += idx * xs7
            yoff += idx * ys7
        if RANK > 6:
            idx = rem % n6
            rem = rem // n6
            xoff += idx * xs6
            yoff += idx * ys6
        if RANK > 5:
            idx = rem % n5
            rem = rem // n5
            xoff += idx * xs5
            yoff += idx * ys5
        if RANK > 4:
            idx = rem % n4
            rem = rem // n4
            xoff += idx * xs4
            yoff += idx * ys4
        if RANK > 3:
            idx = rem % n3
            rem = rem // n3
            xoff += idx * xs3
            yoff += idx * ys3
        if RANK > 2:
            idx = rem % n2
            rem = rem // n2
            xoff += idx * xs2
            yoff += idx * ys2
        if RANK > 1:
            idx = rem % n1
            rem = rem // n1
            xoff += idx * xs1
            yoff += idx * ys1
        if RANK > 0:
            idx = rem % n0
            rem = rem // n0
            xoff += idx * xs0
            yoff += idx * ys0
        mask = offs < n
        x = tl.load(x_ptr + xoff, mask=mask, other=0)
        acc = x.to(tl.float32) - s
        tl.store(y_ptr + yoff, acc.to(y_ptr.dtype.element_ty), mask=mask)


