def _next_pow2(n):
    p = 1
    while p < n:
        p <<= 1
    return p


def _pick_block(n):
    if n <= 0:
        return 16
    b = _next_pow2(n)
    if b < 16:
        b = 16
    if b > 4096:
        b = 4096
    return b


def _launch_one(t, out, s):
    n = t.numel()
    block = _pick_block(n)
    chunks = (n + block - 1) // block
    grid = (chunks if chunks < _MAX_GRID else _MAX_GRID,)
    _sub_contig_kernel[grid](
        t,
        out,
        n,
        s,
        BLOCK=block,
        EVEN=(n % block == 0),
        I64=(n > 0x7FFFFFFF),
    )


def _launch_strided(t, out, s):
    n = t.numel()
    shape = t.shape
    rank = len(shape)
    xs = t.stride()
    ys = out.stride()
    sizes = [1] * _MAX_SLOTS
    xst = [0] * _MAX_SLOTS
    yst = [0] * _MAX_SLOTS
    for d in range(rank):
        sizes[d] = shape[d]
        xst[d] = xs[d]
        yst[d] = ys[d]
    block = _pick_block(n)
    chunks = (n + block - 1) // block
    grid = (chunks if chunks < _MAX_GRID else _MAX_GRID,)
    _sub_strided_kernel[grid](
        t,
        out,
        n,
        sizes[0],
        sizes[1],
        sizes[2],
        sizes[3],
        sizes[4],
        sizes[5],
        sizes[6],
        sizes[7],
        xst[0],
        xst[1],
        xst[2],
        xst[3],
        xst[4],
        xst[5],
        xst[6],
        xst[7],
        yst[0],
        yst[1],
        yst[2],
        yst[3],
        yst[4],
        yst[5],
        yst[6],
        yst[7],
        s,
        RANK=rank,
        BLOCK=block,
    )


def _launch_group(items):
    """items: list of (tensor, out, scalar), contiguous, same dtype/device."""
    k = len(items)
    if k == 0:
        return
    if k == 1:
        t, out, s = items[0]
        _launch_one(t, out, s)
        return

    ns = [0] * _MAX_SLOTS
    dxs = [0] * _MAX_SLOTS
    dys = [0] * _MAX_SLOTS
    scs = [0.0] * _MAX_SLOTS
    total = 0
    nmax = 0
    x0 = items[0][0]
    y0 = items[0][1]
    esize = x0.element_size()
    for i, (t, out, s) in enumerate(items):
        n = t.numel()
        ns[i] = n
        dxs[i] = (t.data_ptr() - x0.data_ptr()) // esize
        dys[i] = (out.data_ptr() - y0.data_ptr()) // esize
        scs[i] = s
        total += n
        if n > nmax:
            nmax = n

    if total <= 16384:
        block = _next_pow2(nmax if nmax > 0 else 1)
        if block < 16:
            block = 16
    else:
        block = 4096

    chunks = [(n + block - 1) // block for n in ns[:k]]
    acc = 0
    bps = [0] * _MAX_SLOTS
    for i in range(k):
        bps[i] = acc
        acc += chunks[i]
    if total > _FUSE_LIMIT or acc > _MAX_GRID:
        for t, out, s in items:
            _launch_one(t, out, s)
        return
    grid = (acc,)
    even = all(n % block == 0 for n in ns[:k])

    _sub_fused_kernel[grid](
        x0,
        y0,
        ns[0],
        ns[1],
        ns[2],
        ns[3],
        ns[4],
        ns[5],
        ns[6],
        ns[7],
        dxs[0],
        dxs[1],
        dxs[2],
        dxs[3],
        dxs[4],
        dxs[5],
        dxs[6],
        dxs[7],
        dys[0],
        dys[1],
        dys[2],
        dys[3],
        dys[4],
        dys[5],
        dys[6],
        dys[7],
        scs[0],
        scs[1],
        scs[2],
        scs[3],
        scs[4],
        scs[5],
        scs[6],
        scs[7],
        bps[1] if k > 1 else 0,
        bps[2] if k > 2 else 0,
        bps[3] if k > 3 else 0,
        bps[4] if k > 4 else 0,
        bps[5] if k > 5 else 0,
        bps[6] if k > 6 else 0,
        bps[7] if k > 7 else 0,
        BLOCK=block,
        NSLOT=k,
        EVEN=even,
    )


def _run(self, scalars):
    tensors = list(self)
    scalars = list(scalars)
    if len(tensors) != len(scalars):
        raise RuntimeError(
            "foreach_sub_scalar_list: expected the same number of tensors and "
            "scalars, but got %d tensors and %d scalars" % (len(tensors), len(scalars))
        )
    outs = []
    group = []
    group_dtype = None
    for t, s in zip(tensors, scalars):
        if not isinstance(t, torch.Tensor):
            raise RuntimeError("foreach_sub_scalar_list: expected a list of Tensors")
        out = torch.empty(t.shape, dtype=t.dtype, device=t.device)
        outs.append(out)
        n = t.numel()
        if n == 0:
            continue
        sf = float(s)
        if not t.is_contiguous():
            _launch_group(group)
            group = []
            group_dtype = None
            _launch_strided(t, out, sf)
            continue
        if group and (len(group) >= _MAX_SLOTS or t.dtype is not group_dtype):
            _launch_group(group)
            group = []
        if not group:
            group_dtype = t.dtype
        group.append((t, out, sf))
    _launch_group(group)
    return outs


def foreach_sub_scalar_list(*args, **kwargs):
    """Entry point: run(self, scalars) -> list[Tensor]."""
    if kwargs:
        self = kwargs.pop("self", None)
        scalars = kwargs.pop("scalars", None)
        if kwargs:
            raise TypeError("unexpected keyword arguments: %r" % sorted(kwargs))
        if self is None and args:
            self = args[0]
            args = args[1:]
        if scalars is None:
            if args:
                scalars = args[0]
                args = args[1:]
            else:
                raise TypeError("run() missing required argument: 'scalars'")
        return _run(self, scalars)
    if len(args) != 2:
        raise TypeError("run() takes exactly 2 positional arguments")
    return _run(args[0], args[1])
